LINES = [{'id': 'rule', 'text': 'In this town, every time you sneeze, you swap bodies with the closest person standing next to you.'}, {'id': 'win', 'text': 'My grandma loves it. Yesterday she sneezed and became a baker, and made forty cupcakes in ten minutes.'}, {'id': 'lose', 'text': 'But Bruno the baker sneezed on Monday and became a pigeon sitter. He still smells like seeds.'}, {'id': 'villain', 'text': 'Mayor Grumble hates being the mayor. He wants the body of Mr. Rich, who owns every gold bar in town.'}, {'id': 'pepper', 'text': 'So he sprinkles pepper on his nose, walks right up to Mr. Rich, and sneezes as loud as he can.'}, {'id': 'swap', 'text': 'Poof! Now Mr. Rich is stuck as the grumpy mayor, and Grumble is counting his gold with a huge grin.'}, {'id': 'chaos', 'text': 'Then he kept going. Sneeze, swap, sneeze, swap. Nine bodies in one morning, and he still wanted more.'}, {'id': 'mess', 'text': 'The whole town was mixed up. Dogs walked on two legs, kids ran the bank, and nobody knew who was who.'}, {'id': 'brave', 'text': 'I am only eight, but I grabbed a tissue, held my nose tight, and marched right up to the mayor.'}, {'id': 'plan', 'text': 'I told him, wait, the closest person to you is my grandma. And Grumble finally stopped smiling.'}, {'id': 'tickle', 'text': 'Grandma pulled a feather from her hat and tickled his nose. Ah, ah, ah-CHOO! He swapped with her.'}, {'id': 'twist', 'text': 'Now the mayor was a ninety-year-old grandma with a bedtime of seven, and a very sore back.'}, {'id': 'law', 'text': "Grandma, now in the mayor's body, made one new law: sneeze swaps only last one hour. Everyone cheered."}, {'id': 'end', 'text': 'Everyone got their own body back, and Grumble finally learned something. Now he sneezes into a tissue, every time.'}, {'id': 'last', 'text': "And me? I still sneeze next to Grandma on purpose. She gives the best hugs, even in a mayor's body."}]
